dict(title='Harvest',type='Interrupt',subtype='Lost Interrupt',original_set='Special Edition',set_icon='Special Edition',destiny='5',icons=['Interrupt'],lore='“Harvest is when I need you the most. It’s only one season more. This year we’ll make enough on the harvest that I’ll be able to hire some more hands.”',game_text='If Luke is in a battle with Owen or Beru, add one battle destiny (two if both). OR If Owen or Beru is on table, retrieve any one card (two if both, four if both present at Lars’ Moisture Farm).'),
